import { useEffect, useId, useRef } from 'react';
import { createPortal } from 'react-dom';
import { Icon } from './Icon.js';
import { t } from '@/i18n/index.js';
import styles from './Sheet.module.css';

interface SheetProps {
  /** The heading row. Omit it for a sheet that carries its own heading. */
  title?: string | undefined;
  onClose: () => void;
  children: React.ReactNode;
}

/**
 * The slide-up sheet the prototype uses for adding words and for pickers.
 * Escape closes it, focus moves inside on open and back on close, and a
 * click on the backdrop dismisses it.
 *
 * It renders into `document.body` rather than where it is written. A
 * `position: fixed` backdrop is only fixed to the viewport while no
 * ancestor has established a containing block, and `transform`, `filter`
 * and `backdrop-filter` all establish one. The notebook's sticky header is
 * glass, so the switcher opened from inside it laid its "full screen"
 * backdrop out inside a 200px-tall header and the sheet came down from the
 * top of the page. Any sheet opened from inside any glass or transformed
 * surface would have done the same, so the fix belongs here and not at the
 * one call site that happened to show it.
 */
export function Sheet({ title, onClose, children }: SheetProps): React.JSX.Element {
  const titleId = useId();
  const panel = useRef<HTMLDivElement>(null);
  const restoreFocus = useRef<HTMLElement | null>(null);
  // Callers usually pass a fresh arrow function on every render. Reading it
  // through a ref keeps the effect below to one run per open, so the panel
  // takes focus once and never steals it back from a field mid-typing.
  const close = useRef(onClose);
  useEffect(() => {
    close.current = onClose;
  });

  useEffect(() => {
    restoreFocus.current = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    panel.current?.focus();

    const onKeyDown = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') {
        event.stopPropagation();
        close.current();
      }
    };
    document.addEventListener('keydown', onKeyDown);
    // The page behind must not scroll while a sheet is open.
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';

    return () => {
      document.removeEventListener('keydown', onKeyDown);
      document.body.style.overflow = previousOverflow;
      restoreFocus.current?.focus();
    };
  }, []);

  return createPortal(
    <div
      className={styles.backdrop}
      onClick={(event) => {
        if (event.target === event.currentTarget) onClose();
      }}
    >
      <div
        className={styles.sheet}
        role="dialog"
        aria-modal="true"
        aria-labelledby={title === undefined ? undefined : titleId}
        tabIndex={-1}
        ref={panel}
      >
        <div className={styles.grip} aria-hidden="true" />
        {title !== undefined && (
          <div className={styles.header}>
            <h2 className={styles.title} id={titleId}>
              {title}
            </h2>
            <button type="button" className={styles.close} onClick={onClose} aria-label={t('action.close')}>
              <Icon name="close" size={18} weight={2} />
            </button>
          </div>
        )}
        {children}
      </div>
    </div>,
    document.body,
  );
}
