import { LANGUAGE_INFO, type LanguageCode } from '@lexpad/core';
import { Sheet } from '@/components/ui/Sheet.js';
import { t, type MessageKey } from '@/i18n/index.js';
import styles from './FreeForYou.module.css';

/** The lead and the paragraphs under it, for one side of one language. */
interface Words {
  lead: MessageKey;
  body: readonly MessageKey[];
}

/**
 * Languages that have words of their own.
 *
 * A sentence about Hafez cannot be written once with a language name dropped
 * into it, so the free languages that deserve their own voice get one.
 * Adding Kurdish later means adding an entry here and its strings, not
 * editing this screen.
 */
const WRITTEN: Record<string, { target: Words; meaning: Words }> = {
  fa: {
    target: {
      lead: 'free.fa.learningLead',
      body: ['free.fa.learningOne', 'free.fa.learningTwo'],
    },
    meaning: {
      lead: 'free.fa.readingLead',
      body: ['free.fa.readingOne', 'free.fa.readingTwo', 'free.fa.readingThree'],
    },
  },
};

/** What any other free language gets: the same promise, no borrowed culture. */
const GENERIC: { target: Words; meaning: Words } = {
  target: { lead: 'free.learningLead', body: ['free.learningOne'] },
  meaning: { lead: 'free.readingLead', body: ['free.readingOne', 'free.readingTwo'] },
};

/** The primary language of a tag: "fa-IR" is "fa", as the server reads it. */
function primary(code: string): string {
  return code.split(/[-_]/)[0]?.toLowerCase() ?? '';
}

/**
 * What somebody sees when they tap the plan and their notebook is one
 * Lexpad never charges for.
 *
 * It is the opposite of a paywall and has to read like it: no price, no plan
 * to choose, nothing to dismiss before carrying on. The answer to "what does
 * this cost me" is already no, and the only job here is to say so and get
 * out of the way.
 *
 * The two sides are not the same reader. Somebody learning the language
 * chose it; somebody whose meanings are in it is who this was built for.
 */
export function FreeForYou({
  side,
  code,
  onClose,
}: {
  side: 'target' | 'meaning';
  code: string;
  onClose: () => void;
}): React.JSX.Element {
  const info = LANGUAGE_INFO[code as LanguageCode] as { name: string } | undefined;
  const language = info?.name ?? code;
  const words = (WRITTEN[primary(code)] ?? GENERIC)[side];

  return (
    <Sheet title={t('free.title')} onClose={onClose}>
      <div className={styles.body}>
        <p className={styles.lead}>{t(words.lead, { language })}</p>
        {words.body.map((key) => (
          <p key={key} className={styles.line}>
            {t(key, { language })}
          </p>
        ))}

        <ul className={styles.perks}>
          <li>{t('free.perkCards')}</li>
          <li>{t('free.perkEverything')}</li>
          <li>{t('free.perkNoCard')}</li>
        </ul>

        <p className={styles.note}>{t('free.note')}</p>

        <button type="button" className={styles.done} onClick={onClose}>
          {t('free.done')}
        </button>
      </div>
    </Sheet>
  );
}
